//! 🛫️ The identical cell visitor emits every interpreted PNG entity and native semantic census.
use semio_framework_os_kernel::sqlite_snapshot::artifact::{Cell,RowWriter};
use semio_framework_value::{ValueError,ValueRefusalKind};
use super::{chunks::Native,compression::Stream};
type Result<T>=std::result::Result<T,ValueError>;
fn ordinal(value:usize)->Result<i64>{i64::try_from(value).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"PNG occurrence ordinal exceeds signed64"))}
fn integers(writer:&mut RowWriter<'_,'_>,table:&str,key:i64,fields:&[u32])->Result<()>{if fields.len()>8{return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"PNG fixed field count"))}let mut cells=[Cell::Null;8];for(at,&value)in fields.iter().enumerate(){cells[at]=Cell::Integer(i64::from(value));}writer.insert_key(table,key,&cells[..fields.len()])}
fn stream(stream:&Stream,writer:&mut RowWriter<'_,'_>)->Result<i64>{let id=writer.insert("png_stream",&[Cell::Integer(1),Cell::Integer(i64::from(stream.cmf)),Cell::Integer(i64::from(stream.flg)),Cell::Integer(i64::from(stream.adler)),Cell::Integer(i64::from(stream.padding)),Cell::Integer(i64::from(stream.padding_bits))])?;for(at,block)in stream.blocks.iter().enumerate(){let key=writer.insert("png_deflate_block",&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(block.final_block)),Cell::Integer(i64::from(block.kind)),Cell::Integer(i64::from(block.alignment)),Cell::Integer(i64::from(block.hlit)),Cell::Integer(i64::from(block.hdist)),Cell::Integer(i64::from(block.hclen))])?;for(at,&length)in block.codes.iter().enumerate(){writer.insert("png_deflate_code",&[Cell::Integer(key),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(length))])?;}for(at,length)in block.lengths.iter().enumerate(){writer.insert("png_deflate_length",&[Cell::Integer(key),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(length.symbol)),Cell::Integer(i64::from(length.extra))])?;}for(at,token)in block.tokens.iter().enumerate(){let(distance,extra)=token.distance.map(|(distance,extra)|(Cell::Integer(i64::from(distance)),Cell::Integer(i64::from(extra)))).unwrap_or((Cell::Null,Cell::Null));writer.insert("png_deflate_token",&[Cell::Integer(key),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(token.symbol)),Cell::Integer(i64::from(token.extra)),distance,extra])?;}}Ok(id)}
pub(super) fn write(schema:&str,native:Option<&Native>,literal:&[u8],writer:&mut RowWriter<'_,'_>)->Result<()>{writer.insert_key("png_document",1,&[Cell::Text(schema),Cell::Text(if native.is_some(){"native"}else{"literal"})])?;let Some(native)=native else{for(at,&value)in literal.iter().enumerate(){writer.insert("png_literal_octet",&[Cell::Integer(1),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(value))])?;}return Ok(())};let image=stream(&native.image,writer)?;
 for(at,chunk)in native.chunks.iter().enumerate(){let kind=std::str::from_utf8(&chunk.kind).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"PNG chunk kind is not ASCII"))?;let id=writer.insert("png_chunk",&[Cell::Integer(1),Cell::Integer(ordinal(at)?),Cell::Text(kind)])?;let f=&chunk.fields;match &chunk.kind{
  b"IHDR"=>integers(writer,"png_ihdr",id,f)?,b"IDAT"=>writer.insert_key("png_idat",id,&[Cell::Integer(image),Cell::Integer(i64::from(f[0]))])?,b"IEND"=>{},
  b"PLTE"=>{for(at,value)in f.chunks_exact(3).enumerate(){writer.insert("png_palette",&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(value[0])),Cell::Integer(i64::from(value[1])),Cell::Integer(i64::from(value[2]))])?;}},
  b"tRNS"|b"bKGD"=>{let table=if chunk.kind==*b"tRNS"{"png_transparency"}else{"png_background"};for(at,&value)in f.iter().enumerate(){writer.insert(table,&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(value))])?;}},
  b"gAMA"=>integers(writer,"png_gamma",id,f)?,b"cHRM"=>integers(writer,"png_chromaticity",id,f)?,b"sRGB"=>integers(writer,"png_srgb",id,f)?,b"pHYs"=>integers(writer,"png_physical",id,f)?,b"tIME"=>integers(writer,"png_time",id,f)?,
  b"tEXt"|b"zTXt"|b"iTXt"=>{let text=chunk.text.as_ref().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"PNG interpreted text owner absent"))?;let stream=if let Some(source)=&text.stream{Cell::Integer(stream(source,writer)?)}else{Cell::Null};writer.insert_key("png_text",id,&[Cell::Text(&text.keyword),Cell::Text(&text.value),Cell::Text(&text.language),Cell::Text(&text.translated),Cell::Integer(i64::from(text.compressed)),stream])?;},
  _=>{for(at,&value)in chunk.octets.iter().enumerate(){writer.insert("png_unknown_octet",&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(value))])?;}},
 }}for(at,row)in native.scanlines.rows.iter().enumerate(){let id=writer.insert("png_scanline",&[Cell::Integer(1),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(row.pass)),Cell::Integer(i64::from(row.row)),Cell::Integer(i64::from(row.width)),Cell::Integer(i64::from(row.channels)),Cell::Integer(i64::from(row.depth)),Cell::Integer(i64::from(row.filter))])?;for(at,&value)in row.samples.iter().enumerate(){writer.insert("png_sample",&[Cell::Integer(id),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(value))])?;}if row.remainder_bits!=0{writer.insert_key("png_packed_remainder",id,&[Cell::Integer(i64::from(row.remainder_bits)),Cell::Integer(i64::from(row.remainder))])?;}}
 for(at,&value)in native.scanlines.tail.iter().enumerate(){writer.insert("png_inflated_tail",&[Cell::Integer(1),Cell::Integer(ordinal(at)?),Cell::Integer(i64::from(value))])?;}Ok(())
}
